import {request,query} from './api.js';
import {badge,closeOverlay,esc,field,fmt,icon,input,num,openDrawer,openModal,pageHead,select,statusType,table,toast,uuid,yuan} from './ui.js';

const app=document.querySelector('#app');
const state={me:null,companies:[],packages:[],currentPage:'dashboard',calendarMonth:null};
const can=code=>state.me?.permissions?.includes('*')||state.me?.permissions?.includes(code);
const adminIcon=name=>window.ZSIconSystem?.svg?.(name)||icon(name);
const INTERNAL_USER_ROLES=[
  ['SUPER_ADMIN','超级管理员'],
  ['OWNER','平台负责人'],
  ['LEAD_ENTRY','录入人员'],
  ['OPERATION','运营人员'],
  ['TELESALES','电销人员'],
  ['FINANCE','积分管理员'],
  ['RETURN_REVIEWER','退回审核员']
];
const BUSINESS_CATEGORIES=[['OLD_RENOVATION','旧房改造'],['SELF_BUILD','农村自建房'],['INTERIOR','室内装修'],['','全部类目']];
const BUSINESS_BRANDS=[['ZHONGSHU','合家美宅'],['PARTNER','合作品牌'],['','全部品牌']];
const MEMBER_LEVELS=[['V1','普通加盟商'],['V2','重点加盟商'],['V3','核心加盟商'],['','全部等级']];
const menu=[
  ['概览',[['dashboard','layout-dashboard','数据看板',()=>can('dashboard.business.read')||can('dashboard.operation.read')||can('dashboard.finance.read')||can('*')]]],
  ['客资运营',[['verification','phone','电销核验任务',()=>can('verification.read')||can('verification.task.read')],['qualified','user-check','合格客资池',()=>can('lead.dispatch')],['assignments','hand-claim','派发订单',()=>can('assignment.read')]]],
  ['加盟商与积分',[['companies','building','加盟商公司',()=>can('company.read')||can('*')],['points','coins','积分规则',()=>can('points.read')||can('points.package.manage')],['recharge','plus','人工充值积分',()=>can('points.recharge')],['ledgers','receipt','积分流水',()=>can('points.read')]]],
  ['质量与系统',[['returns','rotate-ccw','退回审核',()=>can('return.read')||can('return.review')],['calendar','calendar','工作日历',()=>can('calendar.read')],['outbox','bell','通知任务',()=>can('notification.retry')||can('*')],['users','users','账号角色',()=>can('*')],['configs','settings','系统设置',()=>can('*')],['audit','activity','审计日志',()=>can('audit.read')||can('*')]]]
];

function login(){zsSetSafeHtml(app, `<section class="login"><div class="login-brand"><img src="./logo.png" alt="合家美宅"><h1>合家美宅客资管理平台</h1><p>客资审核、派发与积分管理。</p></div><div class="login-form"><div class="login-card"><h2>管理后台登录</h2><p style="color:var(--muted);font-size:13px">按角色展示业务数据。</p>${field('username','账号',input('username','','text','请输入管理账号'))}${field('password','密码',input('password','','password','请输入密码'))}<button id="login-btn" class="btn btn-primary" style="width:100%">登录系统</button></div></div></section>`);document.querySelector('#login-btn').onclick=async()=>{try{await request('/auth/login',{method:'POST',body:JSON.stringify({username:document.querySelector('#username').value,password:document.querySelector('#password').value})});await boot()}catch(e){toast(e.message,'error')}}}
function shell(content,title){const groups=menu.map(([label,items])=>{const valid=items.filter(x=>x[3]());if(!valid.length)return'';return `<div class="menu-label">${label}</div>${valid.map(([r,i,l])=>`<button class="menu-item ${state.currentPage===r?'active':''}" data-route="${r}"><i>${adminIcon(i)}</i>${l}</button>`).join('')}`}).join('');const avatar=esc((state.me.display_name||'用户').slice(0,1));zsSetSafeHtml(app, `<div class="layout"><aside class="sidebar" id="sidebar"><div class="logo"><img src="./logo.png" alt="合家美宅"><div>合家美宅<small>客资管理平台</small></div></div>${groups}</aside><div class="main"><header class="topbar"><div style="display:flex;align-items:center;gap:12px"><button class="btn btn-small btn-outline mobile-menu" id="mobile-menu" type="button" aria-label="打开导航菜单">${adminIcon('menu')}</button><h1>${esc(title)}</h1></div><div class="user"><button class="avatar avatar-button" id="user-menu" type="button" aria-label="打开账号菜单" aria-haspopup="menu" aria-controls="account-menu" aria-expanded="false">${avatar}</button><div class="account-menu" id="account-menu" role="menu" hidden><button id="logout" class="account-menu-item" type="button" role="menuitem">${adminIcon('log-out')}<span>退出登录</span></button></div></div></header><main class="page">${content}</main></div></div>`);bindShell()}
function bindShell(){document.querySelectorAll('[data-route]').forEach(x=>x.onclick=()=>go(x.dataset.route));const userMenu=document.querySelector('#user-menu'),accountMenu=document.querySelector('#account-menu');const closeUserMenu=()=>{accountMenu.hidden=true;userMenu.setAttribute('aria-expanded','false');document.removeEventListener('click',closeUserMenu)};const closeOnEscape=event=>{if(event.key==='Escape'){closeUserMenu();userMenu.focus()}};userMenu.onclick=event=>{event.stopPropagation();const willOpen=accountMenu.hidden;closeUserMenu();if(willOpen){accountMenu.hidden=false;userMenu.setAttribute('aria-expanded','true');document.addEventListener('click',closeUserMenu)}};userMenu.onkeydown=closeOnEscape;accountMenu.onkeydown=closeOnEscape;accountMenu.onclick=event=>event.stopPropagation();document.querySelector('#logout').onclick=async()=>{closeUserMenu();await request('/auth/logout',{method:'POST'}).catch(()=>{});state.me=null;login()};const mm=document.querySelector('#mobile-menu');if(mm)mm.onclick=()=>document.querySelector('#sidebar').classList.toggle('open')}
function go(route){location.hash='#/'+route}
async function auth(){try{state.me=await request('/auth/me');return true}catch(e){login();return false}}
async function boot(){if(!await auth())return;route()}

async function dashboard(){const [summary,trends,sources,alerts]=await Promise.all([request('/dashboard/summary'),request('/dashboard/trends?days=7').catch(()=>null),request('/dashboard/sources').catch(()=>[]),request('/dashboard/alerts').catch(()=>({}))]);const b=summary.business||{},f=summary.finance||{};const cards=[['待处理客资',b.staging||0,'inbox'],['待核验',b.verification_pending||0,'phone'],['合格客资',b.qualified||0,'user-check'],['待领取',b.pending_claim||0,'hand-claim']];if(summary.finance)cards.push(['积分总余额',f.points_balance_total||0,'coins']);const chart=trends?renderChart(trends):'<div class="empty">当前角色不显示平台趋势</div>';const max=Math.max(...sources.map(x=>x.count),1);shell(`${pageHead('运营数据看板','按当前账号权限展示业务指标。')}<section class="cards">${cards.map(([l,v,i])=>`<div class="stat"><div class="icon">${adminIcon(i)}</div><div class="value">${num(v)}</div><div class="label">${l}</div></div>`).join('')}</section><section class="grid-2"><div class="panel"><div class="panel-head"><h3>近7日业务趋势</h3></div>${chart}</div><div class="panel"><div class="panel-head"><h3>渠道来源分布</h3></div><div class="panel-body">${sources.length?sources.map(x=>`<div class="source-row"><span>${esc(x.source)}</span><div class="progress"><i style="width:${x.count/max*100}%"></i></div><b>${x.count}</b></div>`).join(''):'暂无数据'}</div></div></section><section class="panel"><div class="panel-head"><h3>运营预警</h3></div><div class="panel-body cards" style="margin:0">${[['导入异常',alerts.import_errors||0],['疑似重复',alerts.duplicate_reviews||0],['退回待审',alerts.return_reviews||0],['通知失败',alerts.failed_notifications||0]].map(([l,v])=>`<div class="stat"><div class="value">${v}</div><div class="label">${l}</div></div>`).join('')}</div></section>`,'数据看板')}
function renderChart(t){const all=[...t.series.leads,...t.series.assignments,...t.series.followups],max=Math.max(...all,1);return `<div class="chart">${t.labels.map((l,i)=>`<div class="chart-col"><div class="bar-stack"><i class="bar leads" style="height:${t.series.leads[i]/max*100}%"></i><i class="bar assignments" style="height:${t.series.assignments[i]/max*100}%"></i><i class="bar followups" style="height:${t.series.followups[i]/max*100}%"></i></div><span>${l.slice(5)}</span></div>`).join('')}</div><div class="legend"><span><i class="dot" style="background:var(--gold)"></i>新增客资</span><span><i class="dot" style="background:var(--brand)"></i>派发</span><span><i class="dot" style="background:#5b8c70"></i>跟进</span></div>`}

async function staging(){const [d,preview]=await Promise.all([request('/leads/staging?page=1&page_size=100'),request('/leads/staging-cleanup-preview').catch(()=>null)]);const rows=d.items.map(x=>`<tr><td><b>${esc(x.customer_name)}</b><br><span class="sensitive">${esc(x.phone_masked)}</span></td><td>${esc(x.city||'--')} ${esc(x.district||'')}</td><td>${esc(x.source_channel||'--')}</td><td>${badge(x.status,statusType(x.status))}<br><small>${esc(x.pending_reason||'')}</small></td><td>${fmt(x.imported_at)}</td><td><span class="link" data-view-lead="${x.id}">详情</span></td></tr>`);const cleanup=preview?`<section class="panel"><div class="panel-head"><h3>历史导入清理</h3></div><div class="panel-body"><p style="color:var(--muted);margin-top:0">${esc(preview.scope)}</p><div class="cards" style="margin:0 0 14px"><div class="stat"><div class="value">${num(preview.deletable_count)}</div><div class="label">可清理</div></div><div class="stat"><div class="value">${num(preview.blocked_count)}</div><div class="label">已关联保留</div></div></div><button id="cleanup-staging" class="btn btn-danger" ${preview.deletable_count?'':'disabled'}>确认清理可删除记录</button></div></section>`:'';shell(`${pageHead('历史导入暂存','旧导入通道已停用，此页仅用于查看历史暂存数据并清理未进入业务流程的记录。')} ${cleanup}<section class="panel">${table(['客户','地区','来源','状态','导入时间','操作'],rows,'暂无历史暂存记录')}</section>`,'历史导入暂存');const cleanupButton=document.querySelector('#cleanup-staging');if(cleanupButton)cleanupButton.onclick=async()=>{if(!confirm(`确认清理 ${preview.deletable_count} 条未关联历史暂存记录？已进入核验、派发或退回流程的数据会保留。`))return;try{const result=await request('/leads/staging-cleanup',{method:'POST',body:JSON.stringify({confirmed:true,expected_deletable_count:preview.deletable_count,cleanup_token:preview.cleanup_token})});toast(`已清理 ${result.deleted_count} 条历史记录`);staging()}catch(e){toast(e.message,'error')}};document.querySelectorAll('[data-view-lead]').forEach(x=>x.onclick=()=>leadDrawer(x.dataset.viewLead))}
async function leadDrawer(id){try{const [x,issues]=await Promise.all([request('/leads/'+id),request(`/leads/${id}/issues`)]);openDrawer('客资详情',`<dl class="detail-grid">${Object.entries({客户姓名:x.customer_name,手机号:x.phone||x.phone_masked,地区:`${x.city||''} ${x.district||''}`,地区编码:x.region_code,业务类目:x.category_code,品牌:x.brand_code,来源:x.source_channel,需求:x.need_summary,状态:x.status}).map(([k,v])=>`<dt>${k}</dt><dd>${esc(v||'--')}</dd>`).join('')}</dl><h3>导入问题</h3>${issues.length?issues.map(i=>`<p>${badge(i.type,statusType(i.type))} ${esc(i.message)}</p>`).join(''):'<p>无未处理问题</p>'}`)}catch(e){toast(e.message,'error')}}

async function verification(){const d=await request('/verification/tasks?page=1&page_size=100');const rows=d.items.map(x=>`<tr><td>${esc(x.lead.customer_name)}</td><td>${esc(x.lead.phone_masked)}</td><td>${esc(x.lead.city||'--')} ${esc(x.lead.district||'')}</td><td>${esc(x.lead.source_channel||'--')}</td><td>${badge(x.status,statusType(x.status))}</td><td>${fmt(x.assigned_at)}</td><td><span class="link" data-task="${x.id}">查看</span></td></tr>`);shell(`${pageHead('电销核验任务','查看待领取、已分配、核验中和已提交的电话核验任务。')}<section class="panel">${table(['客户','电话','地区','来源','状态','分配时间','操作'],rows,'暂无核验任务')}</section>`,'电销核验任务');document.querySelectorAll('[data-task]').forEach(x=>x.onclick=async()=>{const t=await request('/verification/tasks/'+x.dataset.task);openDrawer('核验任务详情',`<dl class="detail-grid"><dt>客户</dt><dd>${esc(t.lead.customer_name)}</dd><dt>电话</dt><dd>${esc(t.lead.phone||t.lead.phone_masked)}</dd><dt>地区</dt><dd>${esc(t.lead.city||'')} ${esc(t.lead.district||'')}</dd><dt>需求</dt><dd>${esc(t.lead.need_summary||'--')}</dd><dt>状态</dt><dd>${badge(t.status,statusType(t.status))}</dd></dl><h3>模板快照</h3><pre style="white-space:pre-wrap">${esc(JSON.stringify(t.template,null,2))}</pre>`)})}

async function qualified(){const d=await request('/dispatch/qualified-leads?page=1&page_size=100');const rows=d.items.map(x=>`<tr><td><b>${esc(x.customer_name)}</b><br>${esc(x.phone_masked)}</td><td>${esc(x.city||'')} ${esc(x.district||'')}</td><td>${esc(x.category_code||'--')}</td><td>${esc(x.brand_code||'--')}</td><td>${esc(x.source_channel||'--')}</td><td>${fmt(x.verified_at)}</td><td><button class="btn btn-small btn-primary" data-dispatch="${x.id}">选择加盟商</button></td></tr>`);shell(`${pageHead('合格客资池','仅展示通过内部核验且尚未有效派发的客资。')}<section class="panel">${table(['客户','地区','类目','品牌','来源','核验时间','人工派发'],rows,'当前没有待派发客资')}</section>`,'合格客资池');document.querySelectorAll('[data-dispatch]').forEach(x=>x.onclick=()=>dispatchModal(x.dataset.dispatch))}
async function dispatchModal(leadId){try{const c=await request(`/dispatch/leads/${leadId}/candidates`);const body=`<p style="color:var(--muted)">系统按地区、类目、品牌、微信绑定和积分资格筛选候选公司。运营只能看到资格状态，不显示具体积分余额。</p><div class="field"><label>目标加盟商</label><select id="candidate" class="select" style="width:100%">${c.map(x=>`<option value="${x.company_id}" ${x.eligible?'':'disabled'}>${esc(x.company_name)} · ${esc(x.eligibility_label)} · ${num(x.points_price)}积分</option>`).join('')}</select></div><div class="field"><label>派发备注</label><textarea id="dispatch-note" class="textarea" style="width:100%">人工派发</textarea></div>`;openModal('人工派发客资',body,`<button data-close class="btn btn-outline">取消</button><button id="confirm-dispatch" class="btn btn-primary">确认派发</button>`);document.querySelector('#confirm-dispatch').onclick=async()=>{try{await request(`/dispatch/leads/${leadId}`,{method:'POST',body:JSON.stringify({company_id:document.querySelector('#candidate').value,idempotency_key:`admin-${uuid()}`,reason:document.querySelector('#dispatch-note').value})});closeOverlay();toast('客资派发成功');qualified()}catch(e){toast(e.message,'error')}}}catch(e){toast(e.message,'error')}}

async function assignments(){const d=await request('/dispatch/assignments?page=1&page_size=100');const companies=await getCompanies().catch(()=>[]);const cm=Object.fromEntries(companies.map(x=>[x.id,x.name]));const rows=d.items.map(x=>`<tr><td>${esc(x.lead_snapshot.customer_name)}</td><td>${esc(cm[x.company_id]||x.company_id)}</td><td>${esc(x.lead_snapshot.city||'')} ${esc(x.lead_snapshot.district||'')}</td><td>${num(x.points_price)}</td><td>${badge(x.status,statusType(x.status))}</td><td>${fmt(x.assigned_at)}</td><td><span class="link" data-assignment="${x.id}">轨迹</span></td></tr>`);shell(`${pageHead('派发订单','追踪每条客资的指派、领取、跟进、释放和退回状态。')}<section class="panel">${table(['客户','加盟商','地区','积分价格','状态','派发时间','操作'],rows,'暂无派发订单')}</section>`,'派发订单');document.querySelectorAll('[data-assignment]').forEach(x=>x.onclick=async()=>{const a=await request('/dispatch/assignments/'+x.dataset.assignment);openDrawer('派发订单轨迹',`<dl class="detail-grid"><dt>订单ID</dt><dd>${esc(a.id)}</dd><dt>客户</dt><dd>${esc(a.lead_snapshot.customer_name)}</dd><dt>状态</dt><dd>${badge(a.status,statusType(a.status))}</dd><dt>积分价格</dt><dd>${num(a.points_price)}</dd><dt>派发时间</dt><dd>${fmt(a.assigned_at)}</dd></dl><h3>事件时间线</h3>${a.timeline.map(e=>`<p><b>${esc(e.type)}</b> · ${fmt(e.occurred_at)}<br><small>${esc(JSON.stringify(e.payload))}</small></p>`).join('')}`)})}

async function getCompanies(){if(state.companies.length)return state.companies;const d=await request('/companies?page=1&page_size=200');state.companies=d.items;return d.items}
async function companies(){const [d,regions]=await Promise.all([request('/companies?page=1&page_size=200'),request('/master-data/regions')]);state.companies=d.items;const regionNames=Object.fromEntries(regions.map(item=>[item.code,item.name]));const finance=can('points.read')||can('*');const inviter=can('*');const rows=d.items.map(x=>{const serviceAreas=x.region_codes.map(code=>regionNames[code]).filter(Boolean);return `<tr><td><b>${esc(x.name)}</b></td><td>${esc(x.owner_name||'--')}<br>${esc(x.contact_phone_masked||'')}</td><td>${esc(serviceAreas.join('、')||'待设置')}</td><td>${badge(x.status,statusType(x.status))}</td><td>${esc(labelOf(MEMBER_LEVELS,x.level_code))}</td>${finance?`<td>${num(x.points_balance)}</td>`:''}${inviter?`<td><span class="link" data-invite="${x.id}">邀请</span> <span class="link" data-invite-records="${x.id}">邀请记录</span></td>`:''}</tr>`});shell(`${pageHead('加盟商公司','新建时自动开通接单资格、积分账户和所选服务地区。','<button id="new-company" class="btn btn-primary">新建加盟商</button>')}<section class="panel">${table(['公司','负责人','服务地区','状态','等级',...(finance?['积分余额']:[]),...(inviter?['操作']:[])],rows,'暂无加盟商公司')}</section>`,'加盟商公司');document.querySelector('#new-company').onclick=companyModal;document.querySelectorAll('[data-invite]').forEach(x=>x.onclick=()=>{const c=d.items.find(i=>i.id===x.dataset.invite);if(c)inviteConfirmModal(c)});document.querySelectorAll('[data-invite-records]').forEach(x=>x.onclick=()=>{const c=d.items.find(i=>i.id===x.dataset.inviteRecords);if(c)inviteRecordsModal(c)})}
// 邀请链路（P0-01/02/03/08）：按钮 onclick 只弹二次确认，确认后才发创建请求；
// 响应弹窗展示公司/负责人/有效期，提供文案与链接复制、本地二维码、撤销本次邀请。
async function copyToClipboard(text){try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(text);return true}}catch(e){}try{const ta=document.createElement('textarea');ta.value=text;ta.setAttribute('readonly','');ta.style.position='fixed';ta.style.top='-9999px';document.body.appendChild(ta);ta.focus();ta.select();try{return document.execCommand('copy')}finally{ta.remove()}}catch(e){return false}}
// P3-7：两处撤销流程收敛为共享 helper——确认文案与撤销成功提示统一口径。
async function revokeInvite(inviteId,{button,onDone}={}){
  if(!confirm('确认撤销该邀请？撤销后链接与二维码立即失效。'))return false;
  if(button){button.disabled=true;button.textContent='撤销中'}
  try{await request(`/auth/invites/${inviteId}/revoke`,{method:'POST'});toast('邀请已撤销，链接已失效');if(onDone)onDone();return true}
  catch(e){if(button){button.disabled=false;button.textContent='撤销'}toast(e.message,'error');return false}
}
function inviteConfirmModal(company){openModal('生成微信绑定邀请',`<p>将为 <b>${esc(company.name)}</b> 的负责人 <b>${esc(company.owner_name||'（未填写）')}</b> 生成新的绑定邀请。</p><p style="color:var(--danger)">生成后该公司原邀请将立即失效；绑定完成后该公司不可再次邀请。请先核对公司与负责人信息。</p>`,`<button data-close class="btn btn-outline">取消</button><button id="confirm-invite" class="btn btn-primary">确认生成邀请</button>`);document.querySelector('#confirm-invite').onclick=()=>createInviteModal(company)}
async function createInviteModal(company){const btn=document.querySelector('#confirm-invite');if(btn){btn.disabled=true;btn.textContent='生成中'}try{const r=await request(`/auth/companies/${company.id}/invites`,{method:'POST',body:JSON.stringify({expires_hours:72})});openModal('微信绑定邀请（已生成）',`<p>请核对后发送给 <b>${esc(r.company_name)}</b> 的负责人 <b>${esc(r.owner_name||'（未填写）')}</b>，在微信内打开完成确认与授权绑定。</p>${r.revoked_invite_count?`<p style="color:var(--danger)">已自动失效 ${num(r.revoked_invite_count)} 条该公司原邀请。</p>`:''}<div class="field"><label for="invite-copy-text">邀请文案（可直接发送负责人）</label><textarea id="invite-copy-text" class="textarea" style="width:100%">${esc(r.copy_text)}</textarea></div><div class="invite-qr-wrap"><div id="invite-qr"></div><p class="help">二维码内容即邀请链接，仅限该负责人本人使用；转发他人将导致错误绑定。</p></div><p style="color:var(--muted)">有效期至：${fmt(r.expires_at)}</p>`,`<button id="copy-invite-text" class="btn btn-primary">复制完整邀请文案</button><button id="copy-invite-link" class="btn btn-outline">复制链接</button><button id="revoke-invite" class="btn btn-danger">撤销本次邀请</button>`);renderInviteQr(r.url);document.querySelector('#copy-invite-text').onclick=async()=>{const done=await copyToClipboard(r.copy_text);toast(done?'邀请文案已复制':'复制失败，请手动全选文案复制',done?'':'error')};document.querySelector('#copy-invite-link').onclick=async()=>{const done=await copyToClipboard(r.url);toast(done?'邀请链接已复制':'复制失败，请手动复制链接',done?'':'error')};document.querySelector('#revoke-invite').onclick=()=>revokeInvite(r.invite_id,{onDone:closeOverlay})}catch(e){toast(e.message,'error');inviteConfirmModal(company)}}
function renderInviteQr(url){const host=document.querySelector('#invite-qr');if(!host)return;try{if(!window.QRCode)throw new Error('二维码组件未加载');new QRCode(host,{text:url,width:176,height:176,correctLevel:QRCode.CorrectLevel.M})}catch(error){zsSetSafeHtml(host,'<p style="color:var(--danger);margin:0">二维码生成失败，请使用上方邀请文案或“复制链接”发送。</p>')}}
const INVITE_STATUS_META={ACTIVE:['待使用','warn'],USED:['已使用','ok'],REVOKED:['已撤销','bad'],EXPIRED:['已过期','neutral']};
// P1-01/P1-02：邀请记录与使用追溯。接口只读，绝不回显邀请链接；无法核实的
// 追溯字段（历史创建人、历史绑定人）一律显示「未记录」，不用当前值冒充快照。
// P2-01：邀请对象取发出时快照，公司改名后在副行还原当时公司名；存量邀请无快照显示未记录。
async function inviteRecordsModal(company){try{const d=await request(`/auth/companies/${company.id}/invites`);const rows=d.items.map(x=>{const meta=INVITE_STATUS_META[x.status]||[x.status,'neutral'];const invitee=x.invitee_name?`<b>${esc(x.invitee_name)}</b>${x.company_name&&x.company_name!==company.name?`<br><small>发出时公司：${esc(x.company_name)}</small>`:''}`:'未记录';return `<tr><td>${fmt(x.created_at)}</td><td>${esc(x.created_by_name||'未记录')}</td><td>${invitee}</td><td>${badge(meta[0],meta[1])}</td><td>${fmt(x.expires_at)}</td><td>${x.used_at?fmt(x.used_at):'--'}</td><td>${x.status==='USED'?(x.used_by_name?esc(x.used_by_name):'未记录'):'--'}</td><td>${x.status==='ACTIVE'?`<button class="btn btn-small btn-danger" data-revoke="${x.id}">撤销</button>`:'--'}</td></tr>`});openModal(`邀请记录 · ${company.name}`,`<p style="color:var(--muted);margin:0 0 8px">默认显示最近 50 条记录，更早记录仍在系统完整保留，如需核查请联系平台导出；邀请对象为发出时的快照，公司或负责人后续改名不影响历史记录（未留存的显示为未记录）。「使用者」是完成绑定时的微信账号快照，不随公司换绑或数据修复变化；无法核实的显示为未记录。每次生成新邀请会自动作废旧邀请。</p>${table(['创建时间','创建人','邀请对象','状态','过期时间','使用时间','使用者','操作'],rows,'暂无邀请记录')}`,`<button data-close class="btn btn-primary">关闭</button>`);document.querySelectorAll('[data-revoke]').forEach(btn=>btn.onclick=()=>revokeInvite(btn.dataset.revoke,{button:btn,onDone:()=>inviteRecordsModal(company)}))}catch(e){toast(e.message,'error')}}
async function companyModal(){
  try{
    const regionData=await request('/master-data/region-tree');
    const provinces=regionData.provinces||[];
    if(!provinces.length)throw new Error('全国地区数据加载失败');
    openModal('新建加盟商公司',`${field('c-name','公司名称',input('c-name','','text','例如 浦江合家美服务中心'))}${field('c-owner','负责人',input('c-owner','','text','例如 陈经理'))}${field('c-phone','联系电话',input('c-phone','','text','负责人手机号'))}${field('c-province','服务省份',select('c-province',provinces.map(item=>[item.code,item.name])))}${field('c-city','服务城市','<select class="select" id="c-city"></select>')}${field('c-districts','服务区县','<div id="c-districts" style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px"></div>',`全国地区数据（当前覆盖中国大陆省、市、区县，${esc(regionData.year)}年快照），只需下拉选择，无需填写地区编码。默认勾选全城服务；如只服务部分区县，可取消全城后勾选具体区县。`)}${field('c-level','加盟商等级',select('c-level',MEMBER_LEVELS.filter(([v])=>v),'V1'))}`,`<button data-close class="btn btn-outline">取消</button><button id="save-company" class="btn btn-primary">创建</button>`);
    const selectedProvince=()=>provinces.find(item=>item.code===document.querySelector('#c-province').value);
    const selectedCity=()=>selectedProvince()?.cities.find(item=>item.code===document.querySelector('#c-city').value);
    const renderDistricts=()=>{
      const districts=selectedCity()?.districts||[];
      const options=districts.map(item=>`<label style="display:flex;align-items:center;gap:8px"><input type="checkbox" name="c-district" value="${esc(item.code)}" checked>${esc(item.name)}</label>`).join('');
      zsSetSafeHtml(document.querySelector('#c-districts'),`<label style="grid-column:1/-1;display:flex;align-items:center;gap:8px"><input type="checkbox" id="c-serve-all" checked>全城服务</label>${options||'<span style="color:var(--muted)">该城市暂无区县资料，将按城市服务。</span>'}`);
      const all=document.querySelector('#c-serve-all');
      document.querySelectorAll('input[name="c-district"]').forEach(box=>box.onchange=()=>{if(!box.checked)all.checked=false});
      all.onchange=()=>document.querySelectorAll('input[name="c-district"]').forEach(box=>{box.checked=all.checked});
    };
    const renderCities=()=>{
      const cities=selectedProvince()?.cities||[];
      zsSetSafeHtml(document.querySelector('#c-city'),cities.map(item=>`<option value="${esc(item.code)}">${esc(item.name)}</option>`).join(''));
      renderDistricts();
    };
    document.querySelector('#c-province').onchange=renderCities;
    document.querySelector('#c-city').onchange=renderDistricts;
    renderCities();
    document.querySelector('#save-company').onclick=async()=>{
      const serveAll=Boolean(document.querySelector('#c-serve-all')?.checked);
      const districtCodes=[...document.querySelectorAll('input[name="c-district"]:checked')].map(item=>item.value);
      try{
        await request('/companies/simple',{method:'POST',body:JSON.stringify({name:document.querySelector('#c-name').value,owner_name:document.querySelector('#c-owner').value||null,contact_phone:document.querySelector('#c-phone').value||null,primary_city_code:document.querySelector('#c-city').value,district_codes:serveAll?[]:districtCodes,serve_all_districts:serveAll,level_code:document.querySelector('#c-level').value})});
        closeOverlay();state.companies=[];toast('加盟商公司已创建，接单资格和服务地区已同步');companies();
      }catch(e){toast(e.message,'error')}
    };
  }catch(e){toast(e.message,'error')}
}

const labelOf=(options,value)=>options.find(([code])=>code===value)?.[1]||value||'全部';
async function points(){const [packages,rules,cities]=await Promise.all([request('/points/packages?active_only=false'),request('/points/price-rules'),request('/master-data/regions?level=CITY')]);state.packages=packages;const cityNames=Object.fromEntries(cities.map(item=>[item.code,item.name]));const packageRows=packages.map(x=>`<tr><td>${esc(x.name)}</td><td>${yuan(x.cash_amount_cents)}</td><td>${num(x.base_points)}</td><td>${num(x.bonus_points)}</td><td>${num(x.total_points)}</td><td>${esc(labelOf(MEMBER_LEVELS,x.level_code))}</td><td>${badge(x.status,statusType(x.status))}</td></tr>`);const ruleRows=rules.map(x=>`<tr><td>${esc(x.region_code?cityNames[x.region_code]||'已配置地区':'全部地区')}</td><td>${esc(labelOf(BUSINESS_CATEGORIES,x.category_code))}</td><td>${esc(labelOf(BUSINESS_BRANDS,x.brand_code))}</td><td>${esc(labelOf(MEMBER_LEVELS,x.level_code))}</td><td>${num(x.points_cost)}</td><td>${badge(x.status,statusType(x.status))}</td></tr>`);shell(`${pageHead('积分档位与定价','配置线下收款后的充值档位，以及不同地区、业务和加盟商等级的客资积分价格。','<button id="new-package" class="btn btn-primary">新增充值档位</button><button id="new-rule" class="btn btn-outline">新增积分价格规则</button>')}<section class="panel"><div class="panel-head"><h3>充值档位</h3></div>${table(['档位','线下实收','基础积分','赠送积分','到账积分','适用等级','状态'],packageRows)}</section><section class="panel"><div class="panel-head"><h3>客资积分价格</h3></div>${table(['地区','类目','品牌','加盟商等级','领取价格','状态'],ruleRows)}</section>`,'积分规则');document.querySelector('#new-package').onclick=packageModal;document.querySelector('#new-rule').onclick=priceRuleModal}
function packageModal(){openModal('新增充值档位',`${field('p-name','档位名称',input('p-name','50000积分标准档'))}${field('p-cash-yuan','线下实收金额（元）',input('p-cash-yuan','50000','number'))}${field('p-base','基础积分',input('p-base','50000','number'))}${field('p-bonus','赠送积分',input('p-bonus','10000','number'))}${field('p-level','适用等级',select('p-level',MEMBER_LEVELS.filter(([v])=>v),'V2'))}${field('p-benefit','权益说明',input('p-benefit','按已发布客资价格规则扣减积分','text','用于加盟商充值档位展示。'))}`,`<button data-close class="btn btn-outline">取消</button><button id="save-package" class="btn btn-primary">保存并发布</button>`);document.querySelector('#save-package').onclick=async()=>{try{const cashYuan=Number(document.querySelector('#p-cash-yuan').value||0);const basePoints=Number(document.querySelector('#p-base').value||0);const bonusPoints=Number(document.querySelector('#p-bonus').value||0);await request('/points/packages',{method:'POST',body:JSON.stringify({code:`PKG-${basePoints}-${cashYuan}`,name:document.querySelector('#p-name').value,cash_amount_cents:Math.round(cashYuan*100),base_points:basePoints,bonus_points:bonusPoints,level_code:document.querySelector('#p-level').value,entitlements:{benefit_summary:document.querySelector('#p-benefit').value},publish:true})});closeOverlay();toast('充值档位已发布');points()}catch(e){toast(e.message,'error')}}}
function calculatePriceRulePriority({regionCode,categoryCode,brandCode,levelCode}){let priority=1000;if(regionCode)priority-=300;if(categoryCode)priority-=200;if(brandCode)priority-=100;if(levelCode)priority-=50;return priority}
async function priceRuleModal(){try{const cities=await request('/master-data/regions?level=CITY');const regionOptions=[['','全部地区'],...cities.map(city=>[city.code,city.name])];openModal('新增积分价格规则',`${field('price-area','适用地区',select('price-area',regionOptions))}${field('price-category','业务类目',select('price-category',BUSINESS_CATEGORIES,'OLD_RENOVATION'))}${field('price-brand','品牌',select('price-brand',BUSINESS_BRANDS,'ZHONGSHU'))}${field('price-level','加盟商等级',select('price-level',MEMBER_LEVELS,''))}${field('price-points','领取所需积分',input('price-points','100','number'))}<div class="help" id="rule-summary" style="margin-top:-6px;margin-bottom:12px"></div>`,`<button data-close class="btn btn-outline">取消</button><button id="save-rule" class="btn btn-primary">保存并发布</button>`);const value=id=>document.querySelector(id).value||null;const updateSummary=()=>{document.querySelector('#rule-summary').textContent='系统会自动让地区、类目、品牌和等级匹配更具体的规则优先生效。'};['#price-area','#price-category','#price-brand','#price-level'].forEach(id=>document.querySelector(id).onchange=updateSummary);updateSummary();document.querySelector('#save-rule').onclick=async()=>{try{const payload={regionCode:value('#price-area'),categoryCode:value('#price-category'),brandCode:value('#price-brand'),levelCode:value('#price-level')};await request('/points/price-rules',{method:'POST',body:JSON.stringify({region_code:payload.regionCode,category_code:payload.categoryCode,brand_code:payload.brandCode,level_code:payload.levelCode,points_cost:Number(document.querySelector('#price-points').value),priority:calculatePriceRulePriority(payload),publish:true})});closeOverlay();toast('价格规则已发布');points()}catch(e){toast(e.message,'error')}}}catch(e){toast(e.message,'error')}}

async function recharge(){const [companies,packages]=await Promise.all([getCompanies(),request('/points/packages')]);shell(`${pageHead('线下收款人工充值积分','系统不处理在线支付。财务核实线下款项后，选择固定档位并录入唯一付款流水号。')}<section class="panel"><div class="panel-body" style="max-width:720px">${field('rc-company','加盟商公司',select('rc-company',companies.map(x=>[x.id,x.name])))}${field('rc-package','充值档位',select('rc-package',packages.map(x=>[x.id,`${x.name} · ${yuan(x.cash_amount_cents)} · ${num(x.base_points+x.bonus_points)}积分`])))}${field('rc-reference','线下付款流水号',input('rc-reference','','text','银行流水号/收据号，系统全局唯一'))}${field('rc-note','备注','<textarea id="rc-note" class="textarea" style="width:100%"></textarea>')}<button id="do-recharge" class="btn btn-primary">确认人工充值</button></div></section>`,'人工充值积分');document.querySelector('#do-recharge').onclick=async()=>{const p=packages.find(x=>x.id===document.querySelector('#rc-package').value);try{await request('/points/recharge',{method:'POST',body:JSON.stringify({company_id:document.querySelector('#rc-company').value,package_id:p.id,external_reference:document.querySelector('#rc-reference').value,cash_amount_cents:p.cash_amount_cents,note:document.querySelector('#rc-note').value||null,idempotency_key:`recharge-${uuid()}`})});toast('积分已入账并生成不可变流水');document.querySelector('#rc-reference').value=''}catch(e){toast(e.message,'error')}}}

async function ledgers(){const d=await request('/points/ledgers?page=1&page_size=200');const companies=await getCompanies().catch(()=>[]);const cm=Object.fromEntries(companies.map(x=>[x.id,x.name]));const rows=d.items.map(x=>`<tr><td>${fmt(x.created_at)}</td><td>${esc(cm[x.company_id]||x.company_id)}</td><td>${esc(x.type)}</td><td style="font-weight:800;color:${x.delta>=0?'var(--success)':'var(--ink)'}">${x.delta>=0?'+':''}${num(x.delta)}</td><td>${num(x.balance_after)}</td><td>${esc(x.external_reference||'--')}</td><td>${esc(x.business_type)}</td></tr>`);shell(`${pageHead('积分不可变流水','充值、领取扣分、退回返分和冲正均形成独立流水，历史记录不可直接修改。')}<section class="panel">${table(['时间','加盟商','类型','变动','余额','外部流水','业务'],rows,'暂无积分流水')}</section>`,'积分流水')}

async function returnsPage(){const d=await request('/returns?page=1&page_size=100');const rows=d.items.map(x=>`<tr><td>${esc(x.id.slice(0,8))}</td><td>${esc(x.company_id)}</td><td>${esc(x.reason_code)}</td><td>${badge(x.status,statusType(x.status))}</td><td>${fmt(x.submitted_at)}</td><td>${x.refund_points?num(x.refund_points):'--'}</td><td><span class="link" data-return="${x.id}">审核详情</span></td></tr>`);shell(`${pageHead('不合格客资退回审核','供应商必须同时提供沟通截图和电话录音；只有管理员审核通过后才返还实际扣除积分。')}<section class="panel">${table(['申请ID','加盟商','原因','状态','提交时间','返还积分','操作'],rows,'暂无退回申请')}</section>`,'退回审核');document.querySelectorAll('[data-return]').forEach(x=>x.onclick=()=>returnDrawer(x.dataset.return))}
async function returnDrawer(id){try{const r=await request('/returns/'+id);const ev=r.evidences||[];const content=`<dl class="detail-grid"><dt>申请ID</dt><dd>${esc(r.id)}</dd><dt>订单ID</dt><dd>${esc(r.assignment_id)}</dd><dt>原因</dt><dd>${esc(r.reason_code)}</dd><dt>说明</dt><dd>${esc(r.description)}</dd><dt>状态</dt><dd>${badge(r.status,statusType(r.status))}</dd><dt>提交时间</dt><dd>${fmt(r.submitted_at)}</dd></dl><h3>证据材料</h3><div class="evidence-grid">${ev.map(e=>`<div class="evidence"><b>${esc(e.type)}</b><p>${esc(e.original_name)}</p><a target="_blank" href="/api/v1/returns/evidence/${e.id}/download?token=${encodeURIComponent(e.access_token)}">安全查看/播放</a></div>`).join('')}</div>${r.status==='PENDING'?`<div class="field"><label>审核意见</label><textarea id="review-note" class="textarea" style="width:100%"></textarea></div><div class="actions"><button class="btn btn-success" data-review="APPROVE">通过并返积分</button><button class="btn btn-outline" data-review="NEED_MORE">要求补充</button><button class="btn btn-danger" data-review="REJECT">驳回</button></div>`:''}`;openDrawer('退回审核详情',content);document.querySelectorAll('[data-review]').forEach(x=>x.onclick=async()=>{const note=document.querySelector('#review-note').value.trim();if(note.length<2)return toast('请填写审核意见','error');try{await request(`/returns/${id}/review`,{method:'POST',body:JSON.stringify({decision:x.dataset.review,note})});closeOverlay();toast('审核已完成');returnsPage()}catch(e){toast(e.message,'error')}})}catch(e){toast(e.message,'error')}}

const OUTBOX_STATUS_META={FAILED:['重试中','warn'],DEAD:['已死信','bad'],MANUAL_ACTION_REQUIRED:['需人工处理','bad']};
async function outbox(){const [g,f]=await Promise.all([request('/notifications/gate0'),request('/notifications/outbox/failed')]);const rows=f.map(x=>{const meta=OUTBOX_STATUS_META[x.status]||[x.status,'neutral'];return `<tr><td>${esc(x.event_type)}</td><td>${esc(x.aggregate_id)}</td><td>${badge(meta[0],meta[1])}</td><td>${x.attempts}</td><td>${esc(x.last_error||'--')}</td><td>${fmt(x.created_at)}</td><td><button class="btn btn-small btn-outline" data-retry="${x.id}">重试</button></td></tr>`});shell(`${pageHead('微信通知与失败队列','公众号通知采用Outbox异步投递；业务事务成功不因通知失败而回滚。','<button id="process-outbox" class="btn btn-primary">处理待发送队列</button>')}<section class="cards"><div class="stat"><div class="label">公众号配置</div><div class="value">${g.configured?'已配置':'未配置'}</div></div><div class="stat"><div class="label">消息适配器</div><div class="value" style="font-size:18px">${esc(g.message_adapter)}</div></div><div class="stat"><div class="label">开发模拟</div><div class="value">${g.dev_mock?'开启':'关闭'}</div></div></section><section class="panel"><div class="panel-head"><h3>失败与待人工处理任务</h3></div>${table(['事件','业务ID','状态','尝试次数','错误','创建时间','操作'],rows,'当前没有失败通知')}</section>`,'通知任务');document.querySelector('#process-outbox').onclick=async()=>{try{const r=await request('/notifications/jobs/process-outbox?limit=100',{method:'POST'});toast(`处理完成：发送 ${r.sent||0}，失败 ${r.failed||0}，待人工 ${r.manual||0}`);outbox()}catch(e){toast(e.message,'error')}};document.querySelectorAll('[data-retry]').forEach(x=>x.onclick=async()=>{await request(`/notifications/outbox/${x.dataset.retry}/retry`,{method:'POST'});toast('已重新进入待发送队列');outbox()})}

function calendarDayModal(dayValue,item={},lockedDate=false){
  if(!can('calendar.manage'))return toast('无维护权限','error');
  const currentDate=dayValue||`${state.calendarMonth}-01`;
  const isWorkday=typeof item.is_workday==='boolean'?item.is_workday:true;
  const title=lockedDate?'编辑工作日历日期':'单日设定';
  openModal(title,`${field('calendar-day','日期',`<input class="input" id="calendar-day" type="date" value="${esc(currentDate)}" ${lockedDate?'readonly':''}>`,'工作日历按中国时区（Asia/Shanghai）的日期计算。')}${field('calendar-is-workday','是否工作日',select('calendar-is-workday',[['true','工作日'],['false','休息日']],String(isWorkday)))}${field('calendar-holiday-name','节日/说明',input('calendar-holiday-name',item.holiday_name||'','text','例如 国庆节 / 调休工作日'))}<p style="color:var(--muted);margin:8px 0 0">影响范围：${esc(CALENDAR_IMPACT_TEXT)}</p>`,`<button data-close class="btn btn-outline">取消</button><button id="save-calendar-day" class="btn btn-primary">保存</button>`);
  document.querySelector('#save-calendar-day').onclick=event=>runCalendarAction(event.currentTarget,async()=>{
    const selectedDay=document.querySelector('#calendar-day').value.trim();
    if(!selectedDay)throw new Error('请选择日期');
    const payload={is_workday:document.querySelector('#calendar-is-workday').value==='true',holiday_name:document.querySelector('#calendar-holiday-name').value.trim()||null};
    const result=await request(`/admin/v1.2/calendar-days/${selectedDay}`,{method:'PUT',body:JSON.stringify(payload)});
    return result.changed?'工作日历已保存':'配置无变化，未重复写入审计';
  });
}

function calendarDayDrawer(dayValue,item){
  const action=can('calendar.manage')?'<button id="edit-calendar-day" class="btn btn-primary">编辑当天</button>':'<span style="color:var(--muted)">无维护权限，当前为只读查看。</span>';
  const body=`<dl class="detail-grid"><dt>日期</dt><dd>${esc(dayValue)}</dd><dt>状态</dt><dd>${badge(item.is_workday?'工作日':'休息日',item.is_workday?'ok':'neutral')}</dd><dt>设置方式</dt><dd>${esc(item.is_override?'单日调整':'系统默认')}</dd><dt>节日/说明</dt><dd>${esc(item.holiday_name||'--')}</dd><dt>变更人</dt><dd>${esc(calendarDisplayUpdatedBy(item))}</dd><dt>变更时间（中国时区）</dt><dd>${esc(calendarDisplayUpdatedAt(item))}</dd><dt>影响范围</dt><dd>${esc(CALENDAR_IMPACT_TEXT)}</dd></dl><div class="actions">${action}</div>`;
  openDrawer('工作日历详情',body);
  const edit=document.querySelector('#edit-calendar-day');
  if(edit)edit.onclick=()=>calendarDayModal(dayValue,item,true);
}

async function calendar(){
  state.calendarMonth=state.calendarMonth||chinaMonthValue(new Date());
  const range=monthRange(state.calendarMonth);
  const items=await request(`/admin/v1.2/calendar-days?start=${range.start}&end=${range.end}`);
  if(items.length!==range.daysInMonth)throw new Error('工作日历返回的有效日期不完整');
  const byDay=Object.fromEntries(items.map(item=>[item.day,item]));
  const overrides=items.filter(item=>item.is_override);
  const cells=[];
  const leadingDays=(new Date(Date.UTC(range.year,range.month-1,1)).getUTCDay()+6)%7;
  for(let index=0;index<leadingDays;index+=1)cells.push('<div aria-hidden="true" style="min-height:118px;border:1px dashed rgba(0,0,0,.08);border-radius:18px;background:rgba(255,255,255,.45)"></div>');
  items.forEach(item=>{
    const day=Number(item.day.slice(-2));
    cells.push(`<button type="button" data-calendar-day="${item.day}" style="min-height:118px;padding:14px;border-radius:18px;text-align:left;cursor:pointer;${calendarCellTone(item)}"><div style="display:flex;justify-content:space-between;gap:8px;align-items:flex-start"><strong style="font-size:18px">${day}</strong>${badge(item.is_workday?'工作日':'休息日',item.is_workday?'ok':'neutral')}</div><div style="margin-top:8px;font-size:13px;line-height:1.45;color:var(--ink)">${esc(item.holiday_name||(item.is_override?'显式配置':'默认规则'))}</div></button>`);
  });
  const overrideRows=overrides.map(item=>`<tr><td><b>${esc(item.day)}</b></td><td>${badge(item.is_workday?'工作日':'休息日',item.is_workday?'ok':'neutral')}</td><td>${esc(item.holiday_name||'--')}</td><td>${esc(calendarDisplayUpdatedBy(item))}<br><small>${esc(calendarDisplayUpdatedAt(item))}</small></td><td>${esc(CALENDAR_IMPACT_TEXT)}</td>${can('calendar.manage')?`<td><button class="btn btn-small btn-outline" data-calendar-edit="${item.day}">编辑</button></td>`:'<td>只读</td>'}</tr>`);
  const actions=`<div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center"><button id="calendar-prev" class="btn btn-outline">上月</button><input id="calendar-month" class="input" type="month" value="${state.calendarMonth}" style="width:154px"><button id="calendar-next" class="btn btn-outline">下月</button>${can('calendar.manage')?'<button id="calendar-new" class="btn btn-primary">单日设定</button>':'<span style="color:var(--muted)">无维护权限</span>'}</div>`;
  shell(`${pageHead('工作日历','当前按周一至周五计算工作日，周末休息；仅在法定节假日或调休时维护单日例外。',actions)}<section class="panel"><div class="panel-head"><h3>影响说明</h3></div><p style="color:var(--muted)">${esc(CALENDAR_IMPACT_TEXT)}</p></section><section class="cards"><div class="stat"><div class="icon">${adminIcon('calendar')}</div><div class="value">${num(overrides.length)}</div><div class="label">单日例外</div></div><div class="stat"><div class="icon">${adminIcon('sun')}</div><div class="value">${num(items.filter(item=>item.is_workday).length)}</div><div class="label">工作日</div></div><div class="stat"><div class="icon">${adminIcon('moon')}</div><div class="value">${num(items.filter(item=>!item.is_workday).length)}</div><div class="label">休息日</div></div></section><section class="panel"><div class="panel-head"><h3>${state.calendarMonth} 月历</h3><p>点击日期查看有效规则、变更人和变更时间。</p></div><div style="display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:10px;margin-bottom:10px">${CALENDAR_WEEKDAYS.map(label=>`<div style="padding:8px 10px;text-align:center;font-weight:700;color:var(--muted)">${label}</div>`).join('')}</div><div id="calendar-grid" style="display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:10px">${cells.join('')}</div></section><section class="panel"><div class="panel-head"><h3>单日例外列表</h3></div>${table(['日期','状态','节日/说明','变更人/时间','影响范围','操作'],overrideRows,'本月没有单日例外，当前全部使用默认规则。')}</section>`,'工作日历');
  document.querySelector('#calendar-month').onchange=event=>{state.calendarMonth=event.target.value;calendar()};
  document.querySelector('#calendar-prev').onclick=()=>{state.calendarMonth=shiftMonthValue(state.calendarMonth,-1);calendar()};
  document.querySelector('#calendar-next').onclick=()=>{state.calendarMonth=shiftMonthValue(state.calendarMonth,1);calendar()};
  const create=document.querySelector('#calendar-new');
  if(create)create.onclick=()=>calendarDayModal(range.start,byDay[range.start],false);
  document.querySelectorAll('[data-calendar-day]').forEach(button=>button.onclick=()=>calendarDayDrawer(button.dataset.calendarDay,byDay[button.dataset.calendarDay]));
  document.querySelectorAll('[data-calendar-edit]').forEach(button=>button.onclick=()=>calendarDayModal(button.dataset.calendarEdit,byDay[button.dataset.calendarEdit],true));
}

const roleLabels=Object.fromEntries(INTERNAL_USER_ROLES);
const userRoles=x=>(x.roles||x.role_codes||[]).filter(r=>roleLabels[r]);
const roleCheckboxes=(name,selected=[])=>INTERNAL_USER_ROLES.map(([code,label])=>`<label style="display:flex;align-items:center;gap:8px;margin:8px 0"><input type="checkbox" name="${name}" value="${esc(code)}" ${selected.includes(code)?'checked':''}>${esc(label)}</label>`).join('');
const selectedRoleCodes=name=>[...document.querySelectorAll(`input[name="${name}"]:checked`)].map(x=>x.value);
const CHINA_TIMEZONE='Asia/Shanghai';
const CALENDAR_WEEKDAYS=['一','二','三','四','五','六','日'];
const CALENDAR_IMPACT_TEXT='只影响保存后新领取或历史缺失字段补算；已固化的历史截止时间不回算。';
const pad2=value=>String(value).padStart(2,'0');
const chinaDateParts=moment=>Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:CHINA_TIMEZONE,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(moment).filter(part=>part.type!=='literal').map(part=>[part.type,part.value]));
const chinaMonthValue=moment=>{const parts=chinaDateParts(moment);return `${parts.year}-${parts.month}`};
const parseMonthValue=value=>{const [year,month]=value.split('-').map(Number);return {year,month};};
const shiftMonthValue=(value,offset)=>{const {year,month}=parseMonthValue(value);const absolute=year*12+month-1+offset;return `${Math.floor(absolute/12)}-${pad2(absolute%12+1)}`;};
const monthRange=value=>{const {year,month}=parseMonthValue(value);const daysInMonth=new Date(Date.UTC(year,month,0)).getUTCDate();return {year,month,daysInMonth,start:`${value}-01`,end:`${value}-${pad2(daysInMonth)}`};};
const calendarDisplayUpdatedBy=item=>item.updated_by_name||item.updated_by||'系统默认规则';
const calendarDisplayUpdatedAt=item=>item.updated_at?new Date(item.updated_at).toLocaleString('zh-CN',{timeZone:CHINA_TIMEZONE,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):'--';
function calendarCellTone(item){if(item.is_override)return item.is_workday?'border:1px solid rgba(122,98,72,.32);background:linear-gradient(180deg,rgba(122,98,72,.12),rgba(122,98,72,.05));':'border:1px solid rgba(165,75,75,.30);background:linear-gradient(180deg,rgba(165,75,75,.10),rgba(165,75,75,.04));';return item.is_workday?'border:1px solid rgba(0,0,0,.08);background:linear-gradient(180deg,rgba(255,255,255,.94),rgba(245,241,235,.88));':'border:1px solid rgba(0,0,0,.08);background:linear-gradient(180deg,rgba(243,243,243,.92),rgba(232,229,223,.88));';}
async function runCalendarAction(button,action){const old=button.textContent;button.disabled=true;button.textContent='处理中';try{const message=await action();toast(message||'操作完成');closeOverlay();await calendar()}catch(e){toast(e.message,'error')}finally{button.disabled=false;button.textContent=old}}
async function runUserAction(button,action,success){const old=button.textContent;let completed=false;button.disabled=true;button.textContent='处理中';try{await action();completed=true;toast(success);closeOverlay();await users()}catch(e){if(completed&&(e.code==='AUTH_REQUIRED'||e.code==='AUTH_INVALID')){state.me=null;login();toast(`${success}，请重新登录`)}else{toast(e.message,'error')}}finally{button.disabled=false;button.textContent=old}}
async function users(){const data=await request('/users');const internal=data.filter(x=>!x.company_id&&userRoles(x).length);const rows=internal.map(x=>{const roles=userRoles(x);const active=x.status==='ACTIVE';return `<tr><td>${esc(x.display_name)}</td><td>${esc(x.username||'--')}</td><td>${esc(roles.map(r=>roleLabels[r]||r).join('、'))}</td><td>平台内部</td><td>${badge(x.status,statusType(x.status))}</td><td><button class="btn btn-small btn-outline" data-edit-user="${x.id}">编辑角色</button><button class="btn btn-small btn-outline" data-reset-user="${x.id}">重置密码</button>${active?`<button class="btn btn-small btn-danger" data-disable="${x.id}">停用</button>`:`<button class="btn btn-small btn-primary" data-enable="${x.id}">启用</button>`}</td></tr>`});shell(`${pageHead('账号与角色','仅管理平台内部账号；创建、改角色、启停和重置密码都会使相关会话失效。','<button id="new-user" class="btn btn-primary">新建内部账号</button>')}<section class="panel">${table(['姓名','账号','角色','归属','状态','操作'],rows,'暂无内部账号')}</section>`,'账号角色');document.querySelector('#new-user').onclick=userModal;document.querySelectorAll('[data-edit-user]').forEach(x=>x.onclick=()=>editUserRolesModal(internal.find(u=>u.id===x.dataset.editUser)));document.querySelectorAll('[data-reset-user]').forEach(x=>x.onclick=()=>resetUserPasswordModal(internal.find(u=>u.id===x.dataset.resetUser)));document.querySelectorAll('[data-disable]').forEach(x=>x.onclick=()=>{const id=x.dataset.disable;if(confirm('确认停用该账号并使全部会话立即失效？'))runUserAction(x,()=>request(`/users/${id}/disable`,{method:'POST'}),'账号已停用')});document.querySelectorAll('[data-enable]').forEach(x=>x.onclick=()=>{const id=x.dataset.enable;runUserAction(x,()=>request(`/users/${id}/enable`,{method:'POST'}),'账号已启用')})}
function userModal(){openModal('新建内部账号',`${field('u-name','姓名',input('u-name'))}${field('u-user','登录账号',input('u-user'))}${field('u-pass','初始密码',input('u-pass','','password','请设置高强度初始密码'))}${field('u-roles','角色',`<div id="u-roles">${roleCheckboxes('u-role',['OPERATION'])}</div>`,'可多选，仅限平台内部角色。')}`,`<button data-close class="btn btn-outline">取消</button><button id="save-user" class="btn btn-primary">创建</button>`);document.querySelector('#save-user').onclick=x=>runUserAction(x.currentTarget,()=>request('/users',{method:'POST',body:JSON.stringify({username:document.querySelector('#u-user').value,password:document.querySelector('#u-pass').value,display_name:document.querySelector('#u-name').value,role_codes:selectedRoleCodes('u-role')})}),'账号已创建')}
function editUserRolesModal(user){if(!user)return toast('账号不存在','error');openModal('编辑内部账号角色',`<p style="color:var(--muted);margin-top:0">${esc(user.display_name)} · ${esc(user.username||'--')}</p>${field('edit-roles','角色',`<div id="edit-roles">${roleCheckboxes('edit-role',userRoles(user))}</div>`,'保存后该账号现有会话立即失效。')}`,`<button data-close class="btn btn-outline">取消</button><button id="save-user-roles" class="btn btn-primary">保存角色</button>`);document.querySelector('#save-user-roles').onclick=x=>{const id=user.id;runUserAction(x.currentTarget,()=>request(`/users/${id}/roles`,{method:'PUT',body:JSON.stringify({role_codes:selectedRoleCodes('edit-role')})}),'角色已更新')}}
function resetUserPasswordModal(user){if(!user)return toast('账号不存在','error');openModal('重置内部账号密码',`${field('reset-pass','新密码',input('reset-pass','','password','请输入至少12位的高强度密码'))}<p style="color:var(--muted)">保存后该账号现有会话立即失效。</p>`,`<button data-close class="btn btn-outline">取消</button><button id="reset-user-password" class="btn btn-danger">重置密码</button>`);document.querySelector('#reset-user-password').onclick=x=>{const id=user.id;runUserAction(x.currentTarget,()=>request(`/users/${id}/reset-password`,{method:'POST',body:JSON.stringify({new_password:document.querySelector('#reset-pass').value})}),'密码已重置')}}

async function configs(){const cleanup=await request('/leads/staging-cleanup-preview').catch(()=>null);const rows=[`<tr><td>客资领取与退回</td><td>领取后跟进、三工作日申诉和管理员复核按系统默认流程执行。</td><td>${badge('已启用','ok')}</td></tr>`,`<tr><td>积分预警</td><td>加盟商余额不足时按通知任务提醒，阈值由部署环境统一管理。</td><td>${badge('已启用','ok')}</td></tr>`,`<tr><td>工作日历</td><td>默认按周一到周五计算工作日，法定节假日和调休在日历页维护单日例外。</td><td>${badge('已启用','ok')}</td></tr>`];const cleanupPanel=cleanup?`<section class="panel"><div class="panel-head"><h3>历史导入清理</h3></div><div class="panel-body"><p style="color:var(--muted);margin-top:0">${esc(cleanup.scope)}</p><div class="cards" style="margin:0 0 14px"><div class="stat"><div class="value">${num(cleanup.deletable_count)}</div><div class="label">可清理</div></div><div class="stat"><div class="value">${num(cleanup.blocked_count)}</div><div class="label">业务关联保留</div></div></div><button id="settings-cleanup" class="btn btn-danger" ${cleanup.deletable_count?'':'disabled'}>清理未关联历史记录</button></div></section>`:'';shell(`${pageHead('系统设置','这里只保留业务默认规则和清理入口，复杂参数由系统自动维护。')}<section class="panel">${table(['设置项','当前规则','状态'],rows)}</section>${cleanupPanel}`,'系统设置');const cleanupButton=document.querySelector('#settings-cleanup');if(cleanupButton)cleanupButton.onclick=async()=>{if(!confirm(`确认清理 ${cleanup.deletable_count} 条未关联历史记录？`))return;try{const result=await request('/leads/staging-cleanup',{method:'POST',body:JSON.stringify({confirmed:true,expected_deletable_count:cleanup.deletable_count,cleanup_token:cleanup.cleanup_token})});toast(`已清理 ${result.deleted_count} 条历史记录`);configs()}catch(e){toast(e.message,'error')}}}

async function audit(){const d=await request('/audit-logs?page=1&page_size=100');const rows=d.items.map(x=>`<tr><td>${fmt(x.created_at)}</td><td>${esc(x.action)}</td><td>${esc(x.resource_type)}</td><td>${esc(x.resource_id||'--')}</td><td>${esc(x.actor_user_id||'系统')}</td><td><span class="link" data-audit="${x.id}">详情</span></td></tr>`);shell(`${pageHead('操作审计日志','高风险操作记录执行人、角色、请求ID、业务对象、变更前后值与时间。')}<section class="panel">${table(['时间','动作','资源类型','资源ID','操作人','详情'],rows,'暂无审计记录')}</section>`,'审计日志');document.querySelectorAll('[data-audit]').forEach(x=>x.onclick=()=>{const r=d.items.find(i=>i.id===x.dataset.audit);openDrawer('审计详情',`<pre style="white-space:pre-wrap;word-break:break-all">${esc(JSON.stringify(r,null,2))}</pre>`)})}

async function route(){if(!state.me&&!(await auth()))return;const name=location.hash.replace(/^#\/?/,'').split('?')[0]||'dashboard';state.currentPage=name;const handlers={dashboard,staging,verification,qualified,assignments,companies,points,recharge,ledgers,returns:returnsPage,calendar,outbox,users,configs,audit};const fn=handlers[name]||dashboard;try{await fn()}catch(e){console.error(e);if(e.code==='AUTH_REQUIRED'||e.code==='AUTH_INVALID'){state.me=null;login()}else{toast(e.message||'页面加载失败','error');shell(`<div class="empty"><b>${adminIcon('alert-triangle')}</b>${esc(e.message||'页面加载失败')}</div>`,'错误')}}}
window.addEventListener('hashchange',route);boot();
